'use strict';
// mysql2's command shape: the runner reads `this.start`, and a failed prepare assigns an own function over the class's method.
const EventEmitter = require('events').EventEmitter;
class Command extends EventEmitter {
  constructor() {
    super();
    this.next = null;
    this.log = [];
  }
  execute(packet) {
    if (!this.next) {
      this.next = this.start;
    }
    this.next = this.next(packet);
    if (this.next) return false;
    this.emit('end');
    return true;
  }
}
class Execute extends Command {
  start(packet) {
    this.log.push('Execute.start ran');
    return null;
  }
}
class Query extends Command {
  start(packet) {
    this.log.push('Query.start ran');
    return null;
  }
}
function run(failed) {
  const executeCommand = new Execute();
  const prepared = (err) => {
    if (err) {
      executeCommand.start = function () {
        executeCommand.log.push('override ran');
        return null;
      };
    }
  };
  prepared(failed ? new Error('boom') : null);
  executeCommand.execute(null);
  return executeCommand.log.join('|');
}
function runQuery() {
  const q = new Query();
  q.execute(null);
  return q.log.join('|');
}
module.exports = { run, runQuery };
